(3516854, 492440, 29906, '<td valign="top">Extremely creative idea, wonderful execution.</td>', 'Extremely creative idea, wonderful execution.', '2007-04-04 01:07:59.000000', NULL, 1),
(3516863, 492232, 39349, '<td valign="top">WOW! Now that''s a beautiful photograph. Beautiful model and the fill light is perfect. I love the detail in the model''s face and surrounding glow in her dress and the grass. I also think your choice of the slight angled horizon line  works well here. Not much else to say but great work! Can''t really find anything I would change about this shot. Bravo!</td>', 'WOW! Now that''s a beautiful photograph. Beautiful model and the fill light is perfect. I love the detail in the model''s face and surrounding glow in her dress and the grass. I also think your choice of the slight angled horizon line  works well here. Not much else to say but great work! Can''t really find anything I would change about this shot. Bravo!', '2007-04-04 01:10:06.000000', NULL, 1),
(3516872, 492440, 74664, '<td valign="top">holy crap, you got that effect without photoshopping? that''s amazing. 9. Could use some contrast I think</td>', 'holy crap, you got that effect without photoshopping? that''s amazing. 9. Could use some contrast I think', '2007-04-04 01:10:51.000000', NULL, 1),
