(3517897, 490688, 60899, '<td valign="top">Lovely image ...nice contrast and sharpness and perfect composition..9</td>', 'Lovely image ...nice contrast and sharpness and perfect composition..9', '2007-04-04 08:34:59.000000', NULL, 1),
(3517921, 492466, 60899, '<td valign="top">Too dark,the lake is barely visible...and the image lacks sharpness</td>', 'Too dark,the lake is barely visible...and the image lacks sharpness', '2007-04-04 08:43:50.000000', NULL, 1),
(3517928, 491514, 66353, '<td valign="top">Congratulations!<br/>You are the recipient of my comment no. 1000 - and I''m very pleased to tell you that it will be a positive comment.<br/> <br/>This is a very beautiful shot - IMO it''s by far the best of all the flower shots in the challenge. You''ve manged to control the light and avoid extreme burnouts in the highlights and you''ve been able to preserve some detail in the flowers as well.<br/> <br/>For this I''ll give you an 8 for now...</td>', 'Congratulations!You are the recipient of my comment no. 1000 - and I''m very pleased to tell you that it will be a positive comment. This is a very beautiful shot - IMO it''s by far the best of all the flower shots in the challenge. You''ve manged to control the light and avoid extreme burnouts in the highlights and you''ve been able to preserve some detail in the flowers as well. For this I''ll give you an 8 for now...', '2007-04-04 08:45:54.000000', NULL, 1),
(3517940, 489878, 3569, '<td valign="top">Came out quite well.</td>', 'Came out quite well.', '2007-04-04 08:54:09.000000', NULL, 1),
(3517941, 492232, 70689, '<td valign="top">Pretty model, nice balance of front and back lighting. Not too fond of the centered composition, emtpy space arond the model and tilted horizon (6)</td>', 'Pretty model, nice balance of front and back lighting. Not too fond of the centered composition, emtpy space arond the model and tilted horizon (6)', '2007-04-04 08:54:33.000000', NULL, 1),
(3517944, 491520, 70689, '<td valign="top">Been thinking of a similar idea. Like the execution.</td>', 'Been thinking of a similar idea. Like the execution.', '2007-04-04 08:56:30.000000', NULL, 1),
(3517965, 491508, 63700, '<td valign="top">Very Cool!  Very Original!  10 and a Fav.!</td>', 'Very Cool!  Very Original!  10 and a Fav.!', '2007-04-04 09:10:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3517968, 490644, 46885, '<td valign="top">And everyone will go - awww... let''s be kinder. I will, hoping subject relevance and quality will improve.</td>', 'And everyone will go - awww... let''s be kinder. I will, hoping subject relevance and quality will improve.', '2007-04-04 09:11:43.000000', NULL, 1),
(3517973, 492683, 46885, '<td valign="top">Nice one, but begging for better detail and sharpness</td>', 'Nice one, but begging for better detail and sharpness', '2007-04-04 09:13:32.000000', NULL, 1),
(3517978, 492535, 46885, '<td valign="top">It''s the first and probably one of many pictures where I will ask the question - does silouette count for the theme do we differentiate between silouette shot and contre-jour, where there''s a clear subject lit by backlight? I will go half-way and give it a five. Again, it''s a beautiful shot all in all.</td>', 'It''s the first and probably one of many pictures where I will ask the question - does silouette count for the theme do we differentiate between silouette shot and contre-jour, where there''s a clear subject lit by backlight? I will go half-way and give it a five. Again, it''s a beautiful shot all in all.', '2007-04-04 09:15:45.000000', NULL, 1),
(3517982, 490329, 46885, '<td valign="top">Pretty poor...</td>', 'Pretty poor...', '2007-04-04 09:16:43.000000', NULL, 1),
(3517984, 492440, 46885, '<td valign="top">Bit too glam for my liking but I''ll give an extra point for sparkling feeling.</td>', 'Bit too glam for my liking but I''ll give an extra point for sparkling feeling.', '2007-04-04 09:18:17.000000', NULL, 1),
(3517992, 492679, 46885, '<td valign="top">Brilliant, simple and totally on-theme (unlike many shots I''ve seen in this challenge). My only minor complaint is converging vertical and barreling of the window frame - rest of the shot not being obviosly wide-angle, it''s a bit distracting.</td>', 'Brilliant, simple and totally on-theme (unlike many shots I''ve seen in this challenge). My only minor complaint is converging vertical and barreling of the window frame - rest of the shot not being obviosly wide-angle, it''s a bit distracting.', '2007-04-04 09:22:54.000000', NULL, 1),
(3517994, 492357, 46885, '<td valign="top">Noir. May I suggest ''the night before the lambs fell silent''? Good job.</td>', 'Noir. May I suggest ''the night before the lambs fell silent''? Good job.', '2007-04-04 09:23:41.000000', NULL, 1),
(3518018, 489878, 53009, '<td valign="top">Wow this one is really cool !!</td>', 'Wow this one is really cool !!', '2007-04-04 09:30:24.000000', NULL, 1),
(3518025, 490644, 3306, '<td valign="top">Welcome. Good first attempt. Keep ''em comin!</td>', 'Welcome. Good first attempt. Keep ''em comin!', '2007-04-04 09:31:46.000000', NULL, 1),
(3518028, 491257, 3306, '<td valign="top">Interesting light source!</td>', 'Interesting light source!', '2007-04-04 09:32:34.000000', NULL, 1),
(3518035, 490477, 3306, '<td valign="top">Great capture. I''m a sucker for good canine shots. Good luck.</td>', 'Great capture. I''m a sucker for good canine shots. Good luck.', '2007-04-04 09:33:25.000000', NULL, 1),
(3518058, 489878, 17148, '<td valign="top">Is this for real...I mean...WOW...I couldn''t imagine trying to get this perfect. I even like the plane looking slightly blurred. The trail is awesome. One of the coolest images on the site.</td>', 'Is this for real...I mean...WOW...I couldn''t imagine trying to get this perfect. I even like the plane looking slightly blurred. The trail is awesome. One of the coolest images on the site.', '2007-04-04 09:44:19.000000', NULL, 1),
(3518064, 492610, 15711, '<td valign="top">I like this emotive image.  The rainy window and the lace curtain creates a sense of nostalgia. I like the use of negative space to the right of the boy, making the tree outside visible.</td>', 'I like this emotive image.  The rainy window and the lace curtain creates a sense of nostalgia. I like the use of negative space to the right of the boy, making the tree outside visible.', '2007-04-04 09:45:49.000000', NULL, 1),
(3518088, 490120, 61552, '<td valign="top">Nicde shot.  Pretty colors.  No contre-jour, though.</td>', 'Nicde shot.  Pretty colors.  No contre-jour, though.', '2007-04-04 09:56:13.000000', NULL, 1),
(3518115, 492644, 37108, '<td valign="top">Flott vinnsla KV. LY</td>', 'Flott vinnsla KV. LY', '2007-04-04 10:04:47.000000', NULL, 1),
(3518129, 490113, 15711, '<td valign="top">This is cool.  Love the juxtaposition between the woman, the man, the lamp and the dog.  Really arty!!</td>', 'This is cool.  Love the juxtaposition between the woman, the man, the lamp and the dog.  Really arty!!', '2007-04-04 10:07:00.000000', NULL, 1),
(3518131, 492432, 37108, '<td valign="top">There is something missing on this one. I cant put my finger on it but this moment is spectacular and you would have make a great photo of this onw</td>', 'There is something missing on this one. I cant put my finger on it but this moment is spectacular and you would have make a great photo of this onw', '2007-04-04 10:07:10.000000', NULL, 1),
(3518137, 491518, 15711, '<td valign="top">Gorgeous. Lovely set-up.  I like your use of neg. space. Very emotive.</td>', 'Gorgeous. Lovely set-up.  I like your use of neg. space. Very emotive.', '2007-04-04 10:08:24.000000', NULL, 1),
(3518145, 490302, 15711, '<td valign="top">This is really beautiful. He''s bathed in the velvety blue light.  The diagonal line of the guitar neck just adds to the shot.  Lovely work.  My favorite so far.</td>', 'This is really beautiful. He''s bathed in the velvety blue light.  The diagonal line of the guitar neck just adds to the shot.  Lovely work.  My favorite so far.', '2007-04-04 10:10:05.000000', NULL, 1),
(3518173, 492538, 15711, '<td valign="top">This is beautiful. but true contre jour doesn''t have much bokeh as the photographer is looking into the light. I''m sensing it is off to the side somehow.</td>', 'This is beautiful. but true contre jour doesn''t have much bokeh as the photographer is looking into the light. I''m sensing it is off to the side somehow.', '2007-04-04 10:15:42.000000', NULL, 1),
(3518180, 492449, 15711, '<td valign="top">Wonderful.  I like the minimalism.  Great shadow.</td>', 'Wonderful.  I like the minimalism.  Great shadow.', '2007-04-04 10:16:43.000000', NULL, 1),
(3518185, 492424, 15711, '<td valign="top">Perfect example of contre jour.  Love the high contrast it creates.  Great use of neg. space. Very artful. Love the composition.</td>', 'Perfect example of contre jour.  Love the high contrast it creates.  Great use of neg. space. Very artful. Love the composition.', '2007-04-04 10:17:28.000000', NULL, 1),
(3518197, 491604, 66201, '<td valign="top">Lovely work - the freedom of the movement is offset by the sunlight halo giving a general heavenly, spiritual feeling.</td>', 'Lovely work - the freedom of the movement is offset by the sunlight halo giving a general heavenly, spiritual feeling.', '2007-04-04 10:20:37.000000', NULL, 1),
(3518209, 492655, 15711, '<td valign="top">I love that song!!!!  This is lovely. I like that he''s flicking his tail. I also like your choice of duotone. The contre jour is subtle, but I think it suits the challenge well.</td>', 'I love that song!!!!  This is lovely. I like that he''s flicking his tail. I also like your choice of duotone. The contre jour is subtle, but I think it suits the challenge well.', '2007-04-04 10:23:05.000000', NULL, 1),
(3518212, 491714, 15711, '<td valign="top">I really like this.  You can see every detail of her silhouette yet there is a clear background.  Nice work.</td>', 'I really like this.  You can see every detail of her silhouette yet there is a clear background.  Nice work.', '2007-04-04 10:24:10.000000', NULL, 1),
(3518219, 491999, 67999, '<td valign="top">....o.O...how in da heck?</td>', '....o.O...how in da heck?', '2007-04-04 10:25:26.000000', NULL, 1),
(3518220, 491287, 66201, '<td valign="top">I can appreciate how tricky this must have been for you to get the exact placement right. Good effort!</td>', 'I can appreciate how tricky this must have been for you to get the exact placement right. Good effort!', '2007-04-04 10:26:19.000000', NULL, 1),
(3518232, 491257, 15711, '<td valign="top">Holding a flashlight isn''t creating the true sense of contre jour.  There should be a light source illuminating her entire back, not the mottled backdrop.  The shadow on the left is behind her and it should be in front. If I were critiquing this as just a "normal" photo, I''d have her move away from the background, eliminating the shadow altogether. She''s lovely and the tones and contrast are right, but to me, this does not meet the definition of the challenge.</td>', 'Holding a flashlight isn''t creating the true sense of contre jour.  There should be a light source illuminating her entire back, not the mottled backdrop.  The shadow on the left is behind her and it should be in front. If I were critiquing this as just a "normal" photo, I''d have her move away from the background, eliminating the shadow altogether. She''s lovely and the tones and contrast are right, but to me, this does not meet the definition of the challenge.', '2007-04-04 10:29:25.000000', NULL, 1),
(3518241, 491697, 15711, '<td valign="top">This is absolutely stunning.  I love the midtones and shadows, creating silhouette, yet you can still distinguish details on both of the men.  The boat creates a lovely line as well. 10</td>', 'This is absolutely stunning.  I love the midtones and shadows, creating silhouette, yet you can still distinguish details on both of the men.  The boat creates a lovely line as well. 10', '2007-04-04 10:31:43.000000', NULL, 1),
(3518242, 492492, 15711, '<td valign="top">Great diagonal line. Maybe a smidge tight on the crop, but nicely done.</td>', 'Great diagonal line. Maybe a smidge tight on the crop, but nicely done.', '2007-04-04 10:32:20.000000', NULL, 1),
(3518243, 491520, 15711, '<td valign="top">Not a huge fan of mask shots, but this works. I like the "half face" sense of the shadow on the right.</td>', 'Not a huge fan of mask shots, but this works. I like the "half face" sense of the shadow on the right.', '2007-04-04 10:32:45.000000', NULL, 1),
(3518245, 492432, 49109, '<td valign="top">nicely composed. not a typical contre-jour shot IMHO</td>', 'nicely composed. not a typical contre-jour shot IMHO', '2007-04-04 10:33:09.000000', NULL, 1),
(3518248, 490870, 49109, '<td valign="top">good detail, exposure is spot-on! too much sharpening artefacts round the petals and too centered for my taste.</td>', 'good detail, exposure is spot-on! too much sharpening artefacts round the petals and too centered for my taste.', '2007-04-04 10:34:27.000000', NULL, 1),
(3518250, 491717, 66201, '<td valign="top">Intriguing technique - certainly meets the challenge, but it will be interesting to see how the general voters feel about the experimental style... good luck. I think it has a lot of interest Appeal.</td>', 'Intriguing technique - certainly meets the challenge, but it will be interesting to see how the general voters feel about the experimental style... good luck. I think it has a lot of interest Appeal.', '2007-04-04 10:34:49.000000', NULL, 1),
(3518252, 492449, 66201, '<td valign="top">Love the almost sterile nature of the image - simple, under-stated and exact.</td>', 'Love the almost sterile nature of the image - simple, under-stated and exact.', '2007-04-04 10:36:26.000000', NULL, 1),
(3518261, 491884, 66201, '<td valign="top">Delightful composition - I see just enough detail in front of the thistle to create interest (vs flat silhouette) and I like the slate tones.The bee is a nice accessory too.</td>', 'Delightful composition - I see just enough detail in front of the thistle to create interest (vs flat silhouette) and I like the slate tones.The bee is a nice accessory too.', '2007-04-04 10:43:03.000000', NULL, 1),
