(3525759, 491926, 45857, '<td valign="top">like the compostion here, think it might have been stronger if the sun was behind the church.</td>', 'like the compostion here, think it might have been stronger if the sun was behind the church.', '2007-04-06 17:19:41.000000', NULL, 1),
(3525760, 490302, 30049, '<td valign="top">This is different, and kind of nice.  I like how his face is in shadows, yet enough of him is lit up to add interest (shoulders, forearms).  Very creative.  Good luck in the challenge.</td>', 'This is different, and kind of nice.  I like how his face is in shadows, yet enough of him is lit up to add interest (shoulders, forearms).  Very creative.  Good luck in the challenge.', '2007-04-06 17:20:14.000000', NULL, 1),
