(3525768, 491956, 45857, '<td valign="top">Nice work, the tonality really makes it look like a period piece.</td>', 'Nice work, the tonality really makes it look like a period piece.', '2007-04-06 17:22:46.000000', NULL, 1),
(3525776, 491815, 75993, '<td valign="top">Very good job! I like this photo, good composition and on track with challenge; 10/10.</td>', 'Very good job! I like this photo, good composition and on track with challenge; 10/10.', '2007-04-06 17:25:52.000000', NULL, 1),
(3525778, 492431, 30049, '<td valign="top">I love these!  Always SO cool to see it happen AND have a camera handy.  :)  I have a couple shots similar (Landscapes, Shenandoah Scenics).  Well done on this shot of yours.<br/> <br/>Probably getting some hits on whether this meets the challenge or not?  I could see where not really having a "subject" per-se is holding this back.  Although, that being said, it IS shot towards the light.  :)<br/> <br/>This would be a great candidate for trying some HDR/Tonemapping with.<br/> <br/>Anyway, just some observations, and all JMO of course.  :D  Good luck in the challenge.  Oops!  Forgot to mention - LOVE the title!</td>', 'I love these!  Always SO cool to see it happen AND have a camera handy.  :)  I have a couple shots similar (Landscapes, Shenandoah Scenics).  Well done on this shot of yours. Probably getting some hits on whether this meets the challenge or not?  I could see where not really having a "subject" per-se is holding this back.  Although, that being said, it IS shot towards the light.  :) This would be a great candidate for trying some HDR/Tonemapping with. Anyway, just some observations, and all JMO of course.  :D  Good luck in the challenge.  Oops!  Forgot to mention - LOVE the title!', '2007-04-06 17:27:54.000000', NULL, 1),
(3525781, 490283, 30049, '<td valign="top">This site looks familiar!  :)  Nice catch of the light reflecting off of the water.  Good luck in the challenge.</td>', 'This site looks familiar!  :)  Nice catch of the light reflecting off of the water.  Good luck in the challenge.', '2007-04-06 17:29:19.000000', NULL, 1),
